// Partir una dirección virtual de x86-64 (4 niveles) en sus cinco campos
const va = 0x00007f3e0721a1a4n;           // la dirección que vimos en el script de Python

const offset = va & 0xFFFn;               // bits 11..0
const pt     = (va >> 12n) & 0x1FFn;      // bits 20..12
const pd     = (va >> 21n) & 0x1FFn;      // bits 29..21
const pdpt   = (va >> 30n) & 0x1FFn;      // bits 38..30
const pml4   = (va >> 39n) & 0x1FFn;      // bits 47..39

console.log("dirección:", "0x" + va.toString(16));
console.log("binario  :", va.toString(2).padStart(48, "0").replace(/^(.{9})(.{9})(.{9})(.{9})(.{12})$/, "$1 $2 $3 $4 $5"));
console.log("PML4 =", Number(pml4), "| PDPT =", Number(pdpt), "| PD =", Number(pd), "| PT =", Number(pt), "| desplazamiento = 0x" + offset.toString(16));

// El marco que el kernel le asignó a esa página, según /proc/self/pagemap
const marco = 0x1ecbedn;
const fisica = marco * 4096n + offset;    // número de marco × 4096 + desplazamiento
console.log("dirección física: 0x" + fisica.toString(16));

// ¿Cuánto ocuparían las tablas de páginas?
const bitsNumeroPagina = 48 - 12;                       // 36 bits
const entradas = 2 ** bitsNumeroPagina;                 // una tabla plana: una entrada por página posible
console.log("tabla plana:", entradas.toLocaleString("es-AR"), "entradas ×  8 B =", (entradas * 8 / 2 ** 30), "GiB");

function tablasMultinivel(mib) {                        // memoria contigua alineada, en MiB
  const paginas = mib * 256;                            // 1 MiB = 256 páginas de 4 KiB
  const pts = Math.ceil(paginas / 512);                 // cada tabla PT cubre 512 páginas (2 MiB)
  const pds = Math.ceil(pts / 512);
  const pdpts = Math.ceil(pds / 512);
  const total = pts + pds + pdpts + 1;                  // +1 por la raíz (PML4)
  return { paginas, total, kib: total * 4 };
}
for (const mib of [2, 100, 1024]) {
  const r = tablasMultinivel(mib);
  console.log(`${mib} MiB: ${r.paginas.toLocaleString("es-AR")} páginas -> ${r.total} tablas = ${r.kib.toLocaleString("es-AR")} KiB`);
}

